DELETE FROM n8n_chat_histories 
WHERE session_id = '{{ $('When Executed by Another Workflow').item.json.senderId }}' 
  AND (
    message->>'type' = 'tool' 
    OR (message->>'type' = 'ai' AND message->>'content' LIKE 'Calling %')
  );

