// 1. جلب رد الذكاء الاصطناعي ومعرف العميل
let text = $json.output || "";
const triggerData = $('When Executed by Another Workflow').first()?.json || {};
const senderId = triggerData.senderId || "TEST_SESSION_ID";

// 2. فلتر الأمان: تنظيف الماركداون برمجياً قبل الإرسال
text = text.replace(/^#{1,6}\s+/gm, ''); // حذف أي عناوين تبدأ بـ # أو ## أو ###
text = text.replace(/\*\*([^*]+)\*\*/g, '$1'); // حذف رموز التغميق **نص**
text = text.replace(/\*([^*]+)\*/g, '$1'); // حذف رموز الإمالة *نص*
text = text.replace(/`([^`]+)`/g, '$1'); // حذف الـ code `نص`

// 3. تفكيك النص والصور بالاعتماد على صيغة [[IMAGE: url]]
const parts = text.split(/\[\[IMAGE:\s*(https?:\/\/[^\]]+)\]\]/i);
const items = [];

for (let i = 0; i < parts.length; i++) {
  const part = parts[i].trim();
  if (!part) continue;

  if (i % 2 === 1) {
    // جزء الصورة
    items.push({
      json: {
        type: 'image',
        senderId: senderId,
        messagePayload: {
          attachment: {
            type: 'image',
            payload: {
              url: part,
              is_reusable: true
            }
          }
        }
      }
    });
  } else {
    // جزء النص
    items.push({
      json: {
        type: 'text',
        senderId: senderId,
        messagePayload: {
          text: part
        }
      }
    });
  }
}

// أمان إضافي في حال كان الرد نصاً فقط
if (items.length === 0 && text.trim().length > 0) {
  items.push({
    json: {
      type: 'text',
      senderId: senderId,
      messagePayload: {
        text: text.trim()
      }
    }
  });
}

return items;

const text = $json.output || "";
const triggerData = $('When Executed by Another Workflow').first()?.json || {};
const senderId = triggerData.senderId || "TEST_SESSION_ID";

// 1. استخراج جميع روابط الصور
const imageRegex = /\[\[IMAGE:\s*(https?:\/\/[^\]]+)\]\]/gi;
const images = [];
let match;
while ((match = imageRegex.exec(text)) !== null) {
  images.push(match[1]);
}

// 2. تنظيف النص الصوتي: حذف وسوم الصور بالكامل
let speechText = text.replace(/\[\[IMAGE:\s*https?:\/\/[^\]]+\]\]/gi, "").trim();

// 3. تنظيف رموز الماركداون التي قد تشوش على نموذج النطق
speechText = speechText.replace(/[*#_`~]/g, "").trim();

return [{
  json: {
    senderId: senderId,
    speechText: speechText,
    images: images,
    hasImages: images.length > 0
  }
}];

const items = $input.all();
const results = [];

function createWavHeader(dataLength, sampleRate = 24000, numChannels = 1, bitsPerSample = 16) {
  const byteRate = sampleRate * numChannels * bitsPerSample / 8;
  const blockAlign = numChannels * bitsPerSample / 8;
  const buffer = Buffer.alloc(44);
  buffer.write('RIFF', 0);
  buffer.writeUInt32LE(36 + dataLength, 4);
  buffer.write('WAVE', 8);
  buffer.write('fmt ', 12);
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(numChannels, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(byteRate, 28);
  buffer.writeUInt16LE(blockAlign, 32);
  buffer.writeUInt16LE(bitsPerSample, 34);
  buffer.write('data', 36);
  buffer.writeUInt32LE(dataLength, 40);
  return buffer;
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  if (!item.binary || Object.keys(item.binary).length === 0) {
    throw new Error(`العنصر ${i}: ماكاين حتى binary field.`);
  }

  // ناخذو أول binary field موجود، كيفما كان اسمو
  const binaryFieldName = Object.keys(item.binary)[0];

  const pcmBuffer = await this.helpers.getBinaryDataBuffer(i, binaryFieldName);
  const wavHeader = createWavHeader(pcmBuffer.length);
  const wavBuffer = Buffer.concat([wavHeader, pcmBuffer]);

  item.binary.audio_wav = await this.helpers.prepareBinaryData(wavBuffer, 'speech.wav', 'audio/wav');
  results.push(item);
}

return results;

const images = $('Prepare Voice & Images').first().json.images || [];
const senderId = $('Prepare Voice & Images').first().json.senderId;
return images.map(url => ({
  json: {
    senderId: senderId,
    messagePayload: {
      attachment: {
        type: 'image',
        payload: {
          url: url,
          is_reusable: true
        }
      }
    }
  }
}));

